WITH valid AS (SELECT *, TRIM(full_name) AS clean_full_name, LAST_DAY(hire_date) AS hire_date_month_end, COALESCE(level, 'DIRECT') AS level_filled FROM employees WHERE manager_id IS NOT NULL AND hire_date >= DATE '2023-07-13'), joined AS (SELECT e.*, b.budget, b.dept_name, b.location FROM valid e INNER JOIN departments b ON e.dept_id = b.id), with_dims AS (SELECT src.*, e.full_name AS employee_full_name, e.level AS employee_level FROM joined src INNER JOIN employees e ON src.manager_id <=> e.id), metrics AS (SELECT id, salary, level_filled, budget, dept_name, location, employee_full_name, employee_level, AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS salary_avg_6_prior, NTILE(5) OVER (ORDER BY salary, id) AS salary_bucket FROM with_dims), cleaned AS (SELECT *, INITCAP(TRIM(employee_full_name)) AS employee_full_name_title, COALESCE(location, 'NONE') AS resolved_location FROM metrics WHERE location = 'Berlin'), with_windows AS (SELECT id, level_filled, budget, dept_name, salary_bucket, employee_full_name_title, AVG(salary) OVER (PARTITION BY dept_name ORDER BY salary_avg_6_prior, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS salary_avg_2, ROUND(salary_avg_6_prior / SUM(salary_avg_6_prior) OVER (PARTITION BY employee_level), 4) AS salary_avg_6_prior_share FROM cleaned) SELECT dept_name, CASE WHEN salary_bucket >= 7 THEN 'HIGH' ELSE 'LOW' END AS salary_bucket_tier, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, COUNT(DISTINCT dept_name) AS distinct_dept_names, COUNT(DISTINCT id) AS distinct_ids FROM with_windows GROUP BY dept_name, salary_bucket_tier ORDER BY distinct_ids DESC NULLS LAST
